import { tags } from "typia";

/**
 * Search query distribution analysis by economic discussion categories.
 *
 * Shows how search activity is distributed across different topic areas within
 * the economic discussion platform, helping identify which categories generate
 * the most search interest and content discovery demand. This analytics data
 * supports content strategy decisions by revealing trending topics and
 * underrepresented areas that may need more content development.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISearchCategoryBreakdown = {
  /**
   * Unique category code identifier used for internal reference and API
   * operations. Maps to the category_code field in
   * economic_discussion_categories table.
   */
  category_code: string;

  /**
   * Display name for the economic discussion category as shown to users in
   * the interface and search filters.
   */
  category_name: string;

  /**
   * Total number of search queries associated with this category during the
   * analyzed time period. Used to measure category-specific search demand.
   */
  search_count: number & tags.Type<"int32">;

  /**
   * Percentage of total searches that belong to this category, represented as
   * decimal value (0.0 to 1.0). Calculated as search_count divided by total
   * platform searches.
   */
  percentage_of_total: number & tags.Minimum<0> & tags.Maximum<1>;

  /**
   * Average number of results returned for queries in this category.
   * Indicates search effectiveness and content availability for the category
   * topic.
   */
  avg_results_per_query?: number | undefined;
};
